// ==UserScript==
// @name         FactionLedgerIQ
// @namespace    FactionLedgerIQ
// @version      1.0.3
// @description  Simple TornPDA-first faction inventory, raffle ownership, claims, receipts, and leadership audit.
// @match        *://www.torn.com/*
// @match        *://torn.com/*
// @grant        none
// ==/UserScript==

(function () {
'use strict';

const VERSION='1.0.3';
const STATE_KEY='factionledgeriq_v1_state';
const DOCK_ID='factionledgeriq-v1-dock-btn';
const PANEL_ID='factionledgeriq-v1-panel';
const STYLE_ID='factionledgeriq-v1-style';
const P='PERSONAL', F='FACTION', INV='PERSONAL_INVENTORY', DISP='DISPLAY_CASE';

const DEFAULT={
  schemaVersion:1,
  settings:{playerName:'',playerId:'',factionName:'',apiKey:'',apiPolling:true,apiPollSeconds:15,displayTracking:false,showAllFactionItems:false},
  whitelist:[],market:{},lots:[],movements:[],claims:[],raffles:[],pendingTransfers:[],receiptBatches:[],auditClaims:[],paymentBatches:[],processedLogIds:[],
  diagnostics:{apiStatus:'Not configured',lastSyncAt:'',lastApiError:'',lastLogCount:0},
  createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()
};
let state=loadState(),activeTab='home',dockObserver=null,dockQueued=false,apiTimer=null,apiBusy=false,itemCatalog=[],itemCatalogLoadedAt=0,currentAudit=null;

function clone(v){return JSON.parse(JSON.stringify(v));}
function loadState(){try{const r=localStorage.getItem(STATE_KEY);if(!r)return clone(DEFAULT);const x=JSON.parse(r);return {...clone(DEFAULT),...x,settings:{...DEFAULT.settings,...(x.settings||{})},diagnostics:{...DEFAULT.diagnostics,...(x.diagnostics||{})},whitelist:Array.isArray(x.whitelist)?x.whitelist:[],market:x.market||{},lots:Array.isArray(x.lots)?x.lots:[],movements:Array.isArray(x.movements)?x.movements:[],claims:Array.isArray(x.claims)?x.claims:[],raffles:Array.isArray(x.raffles)?x.raffles:[],pendingTransfers:Array.isArray(x.pendingTransfers)?x.pendingTransfers:[],receiptBatches:Array.isArray(x.receiptBatches)?x.receiptBatches:[],auditClaims:Array.isArray(x.auditClaims)?x.auditClaims:[],paymentBatches:Array.isArray(x.paymentBatches)?x.paymentBatches:[],processedLogIds:Array.isArray(x.processedLogIds)?x.processedLogIds:[]};}catch(e){console.warn('[FLIQ] state load failed',e);return clone(DEFAULT);}}
function trackedItemIds(){const ids=new Set();(state.whitelist||[]).forEach(x=>x&&x.itemId&&ids.add(String(x.itemId)));(state.lots||[]).forEach(x=>x&&x.itemId&&ids.add(String(x.itemId)));(state.movements||[]).forEach(x=>x&&x.itemId&&ids.add(String(x.itemId)));(state.claims||[]).forEach(x=>x&&x.itemId&&ids.add(String(x.itemId)));(state.pendingTransfers||[]).forEach(x=>x&&x.itemId&&ids.add(String(x.itemId)));return ids;}
function syncTrackedMarket(){const ids=trackedItemIds(),old=state.market||{},next={};ids.forEach(id=>{const live=itemCatalog.find(x=>String(x.id)===String(id)),prev=old[id];if(live)next[id]={itemId:String(live.id),itemName:live.name,mv:Number(live.marketValue||0),updatedAt:new Date().toISOString()};else if(prev)next[id]=prev;});state.market=next;}
function save(renderAfter=true){state.updatedAt=new Date().toISOString();syncTrackedMarket();const payload=JSON.stringify(state);try{localStorage.setItem(STATE_KEY,payload);}catch(e){if(e&&(e.name==='QuotaExceededError'||/quota/i.test(String(e)))){state.market={};localStorage.setItem(STATE_KEY,JSON.stringify(state));}else throw e;}if(renderAfter)render();}
function uid(p){return (p||'FLIQ')+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,8).toUpperCase();}
function esc(v){return String(v==null?'':v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');}
function money(v){return '$'+Math.round(Number(v||0)).toLocaleString();}
function fmt(v){const d=new Date(v);return Number.isFinite(d.getTime())?d.toLocaleString():'';}
function norm(v){return String(v||'').trim().replace(/\s+/g,' ').toLowerCase();}
function toast(msg){let e=document.getElementById('fliq-v1-toast');if(!e){e=document.createElement('div');e.id='fliq-v1-toast';document.body.appendChild(e);}e.textContent=msg;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),2800);}

function apiKey(){return String(state.settings.apiKey||'').trim();}
function apiUrl(path,params){const q=new URLSearchParams(params||{});q.set('key',apiKey());q.set('comment','FactionLedgerIQ');return 'https://api.torn.com/v2/'+String(path).replace(/^\/+/, '')+'?'+q.toString();}
async function apiFetch(path,params){if(!apiKey())throw new Error('API key not configured');const r=await fetch(apiUrl(path,params),{credentials:'omit',cache:'no-store'});const d=await r.json();if(!r.ok||(d&&d.error)){const e=d&&d.error;throw new Error(e?(e.error||e.message||JSON.stringify(e)):('HTTP '+r.status));}return d;}
function logArray(d){if(!d)return[];const s=d.log!=null?d.log:(d.logs!=null?d.logs:d);if(Array.isArray(s))return s;if(s&&typeof s==='object')return Object.keys(s).map(k=>{const r=s[k];return r&&typeof r==='object'?{id:r.id||k,...r}:null;}).filter(Boolean);return[];}
function logId(l){return String(l&&(l.id||l.log_id||l.logId||l.ID)||'');}
function seen(id){return !!id&&state.processedLogIds.includes(String(id));}
function remember(id){id=String(id||'');if(!id||seen(id))return;state.processedLogIds.push(id);if(state.processedLogIds.length>2500)state.processedLogIds=state.processedLogIds.slice(-2500);}

function normalizeCatalog(data){const s=data&&(data.items||data),out=[];const add=(item,key)=>{if(!item||typeof item!=='object')return;const id=String(item.id||item.item_id||key||'').trim(),name=String(item.name||item.item_name||'').trim(),mv=Number(item.market_value||item.marketValue||(item.value&&(item.value.market_price||item.value.market_value))||0)||0;if(id&&name)out.push({id,name,marketValue:mv});};if(Array.isArray(s))s.forEach(x=>add(x,''));else if(s&&typeof s==='object')Object.keys(s).forEach(k=>add(s[k],k));return out.sort((a,b)=>a.name.localeCompare(b.name));}
async function ensureCatalog(force=false){if(!force&&itemCatalog.length&&Date.now()-itemCatalogLoadedAt<3600000)return itemCatalog;const d=await apiFetch('torn/items',{cat:'All'});const p=normalizeCatalog(d);if(!p.length)throw new Error('No items returned by Torn API');itemCatalog=p;itemCatalogLoadedAt=Date.now();syncTrackedMarket();return p;}
function itemById(id){id=String(id||'');return itemCatalog.find(x=>String(x.id)===id)||(state.market[id]?{id,name:state.market[id].itemName||('Item #'+id),marketValue:Number(state.market[id].mv||0)}:null);}
function itemName(id){const x=itemById(id);return x?x.name:'Item #'+id;}
function mv(id){const x=itemById(id);return x?Number(x.marketValue||0):Number(state.market[String(id)]&&state.market[String(id)].mv||0);}
function whitelist(id,name){id=String(id||'');const n=norm(name);return state.whitelist.find(w=>(id&&String(w.itemId)===id)||(n&&norm(w.itemName)===n))||null;}
function purgePreWhitelistPurchases(){let changed=false;(state.lots||[]).forEach(l=>{if(!l||l.status==='VOID'||l.sourceType!=='PURCHASE')return;const w=whitelist(l.itemId,l.itemName);if(!w||!w.addedAt)return;const created=new Date(l.createdAt||0).getTime(),added=new Date(w.addedAt).getTime();if(Number.isFinite(created)&&Number.isFinite(added)&&created<added&&Number(l.qtyRemaining||0)===Number(l.qtyOriginal||0)){l.status='VOID';l.qtyRemaining=0;l.voidedAt=new Date().toISOString();l.voidReason='Purchase occurred before item was whitelisted';changed=true;}});return changed;}
function trackingStartMs(){const ms=new Date(state.createdAt||0).getTime();return Number.isFinite(ms)&&ms>0?ms:0;}
function logAfterTrackingStart(log){const start=trackingStartMs(),ts=Number(log&&log.timestamp||0)*1000;return !start||!ts||ts>=start;}
function purgePreTrackingEvents(){const start=trackingStartMs();if(!start)return false;let changed=false;(state.movements||[]).forEach(m=>{if(!m||m.status==='VOID'||!['ARMORY_IN','ARMORY_OUT'].includes(m.type)||m.receiptBatchId||(m.claimIds||[]).length)return;const ts=new Date(m.timestamp||0).getTime();if(Number.isFinite(ts)&&ts<start){m.status='VOID';m.voidedAt=new Date().toISOString();m.voidReason='Movement occurred before LedgerIQ tracking started';changed=true;}});(state.lots||[]).forEach(l=>{if(!l||l.status==='VOID'||l.sourceType!=='ARMORY_WITHDRAWAL')return;const ts=new Date(l.createdAt||0).getTime();if(Number.isFinite(ts)&&ts<start&&Number(l.qtyRemaining||0)===Number(l.qtyOriginal||0)){l.status='VOID';l.qtyRemaining=0;l.voidedAt=new Date().toISOString();l.voidReason='Armory withdrawal occurred before LedgerIQ tracking started';changed=true;}});(state.pendingTransfers||[]).forEach(t=>{if(!t||t.status!=='PENDING')return;const ts=new Date(t.timestamp||0).getTime();if(Number.isFinite(ts)&&ts<start){t.status='VOID';t.voidedAt=new Date().toISOString();changed=true;}});return changed;}
function parseItem(v){const t=String(v||'').trim(),m=t.match(/\[(\d+)\]\s*$/)||t.match(/^(\d+)$/);if(m)return itemById(m[1])||{id:m[1],name:itemName(m[1]),marketValue:mv(m[1])};const n=norm(t),x=itemCatalog.find(i=>norm(i.name)===n);if(x)return x;const y=Object.values(state.market).find(i=>norm(i.itemName)===n);return y?{id:String(y.itemId),name:y.itemName,marketValue:Number(y.mv||0)}:null;}

function activeLots(){return state.lots.filter(l=>l.status!=='VOID'&&Number(l.qtyRemaining||0)>0);}
function lotsFor(id,owner,loc){return activeLots().filter(l=>String(l.itemId)===String(id)&&(!owner||l.owner===owner)&&(!loc||l.location===loc)).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));}
function balance(id,owner,loc){return lotsFor(id,owner,loc).reduce((n,l)=>n+Number(l.qtyRemaining||0),0);}
function addLot(o){const q=Math.max(0,Number(o.qty||0));if(!q)return null;const l={id:uid('LOT'),rootId:o.rootId||'',itemId:String(o.itemId||''),itemName:o.itemName||itemName(o.itemId),owner:o.owner,location:o.location,qtyOriginal:q,qtyRemaining:q,sourceType:o.sourceType||'OPENING',sourceRef:o.sourceRef||'',costBasisKnown:o.costBasisKnown===true,costEach:Math.max(0,Number(o.costEach||0)),mvAtSource:Math.max(0,Number(o.mvAtSource!=null?o.mvAtSource:mv(o.itemId))),createdAt:o.createdAt||new Date().toISOString(),notes:o.notes||'',status:'OPEN'};if(!l.rootId)l.rootId=l.id;state.lots.push(l);return l;}
function consume(id,owner,loc,qty,movementId){let rem=Math.max(0,Number(qty||0));const allocations=[];for(const l of lotsFor(id,owner,loc)){if(rem<=0)break;const take=Math.min(rem,Number(l.qtyRemaining||0));if(!take)continue;l.qtyRemaining-=take;if(l.qtyRemaining<=0){l.qtyRemaining=0;l.status='CONSUMED';}allocations.push({id:uid('ALLOC'),movementId,lotId:l.id,rootId:l.rootId||l.id,itemId:String(id),owner,location:loc,qty:take,sourceType:l.sourceType,costBasisKnown:l.costBasisKnown===true,costEach:Number(l.costEach||0),mvAtSource:Number(l.mvAtSource||0)});rem-=take;}return{allocations,unresolved:rem};}
function personalValue(owner){return activeLots().filter(l=>!owner||l.owner===owner).reduce((s,l)=>s+mv(l.itemId)*Number(l.qtyRemaining||0),0);}
function openClaimTotal(){return state.claims.filter(c=>c.status==='OPEN'||c.status==='SUBMITTED').reduce((s,c)=>s+Number(c.amount||0),0);}
function claimById(id){return state.claims.find(c=>c.id===id)||null;}
function movementById(id){return state.movements.find(m=>m.id===id)||null;}

function makeClaim(m,a,mvEach){if(a.owner!==P||!a.qty)return null;const paid=a.costBasisKnown?Number(a.costEach||0):0,owedEach=a.costBasisKnown?Math.max(paid,mvEach):mvEach,c={id:uid('CLM'),movementId:m.id,itemId:m.itemId,itemName:m.itemName,qty:Number(a.qty),paidEach:paid,costBasisKnown:a.costBasisKnown===true,mvEachFrozen:mvEach,amount:Math.round(owedEach*Number(a.qty)),status:'OPEN',createdAt:new Date().toISOString(),submittedAt:'',reimbursedAt:'',voidedAt:'',voidReason:''};state.claims.push(c);return c;}

function armoryOut(o){const id=String(o.itemId),q=Math.max(1,Number(o.qty||1)),m={id:uid('MOV'),type:'ARMORY_OUT',itemId:id,itemName:o.itemName||itemName(id),qty:q,from:'FACTION_ARMORY',to:INV,timestamp:o.timestamp||new Date().toISOString(),apiVerified:o.apiVerified===true,apiLogIds:o.apiLogIds||[],mvEachFrozen:Number(o.mvEach!=null?o.mvEach:mv(id)),allocations:[{owner:F,qty:q,sourceType:'ARMORY_WITHDRAWAL'}],claimIds:[],receiptBatchId:'',status:'ACTIVE',notes:'Faction-owned item withdrawn from Armory.'};state.movements.push(m);addLot({itemId:id,itemName:m.itemName,owner:F,location:INV,qty:q,sourceType:'ARMORY_WITHDRAWAL',sourceRef:m.id,costBasisKnown:false,mvAtSource:m.mvEachFrozen,createdAt:m.timestamp,notes:'Faction-owned while held by member.'});return m;}
function armoryIn(o){const id=String(o.itemId),q=Math.max(1,Number(o.qty||1)),price=Math.max(0,Number(o.mvEach!=null?o.mvEach:mv(id))),fBefore=balance(id,F,INV),pBefore=balance(id,P,INV);let fq=o.factionQty==null?Math.min(q,fBefore):Number(o.factionQty),pq=o.personalQty==null?q-fq:Number(o.personalQty);if(fq+pq!==q)throw new Error('Ownership allocation must equal deposit quantity');if(fq>fBefore)throw new Error('Not enough faction-owned stock');if(pq>pBefore){const missing=pq-pBefore;if(!whitelist(id,o.itemName)||fBefore>fq)throw new Error('Not enough verified personal stock for that ownership change');addLot({itemId:id,itemName:o.itemName||itemName(id),owner:P,location:INV,qty:missing,sourceType:'INFERRED_PERSONAL',costBasisKnown:false,mvAtSource:price,createdAt:o.timestamp||new Date().toISOString(),notes:'Personal stock inferred from API-confirmed whitelisted Armory deposit.'});}
 const m={id:uid('MOV'),type:'ARMORY_IN',itemId:id,itemName:o.itemName||itemName(id),qty:q,from:INV,to:'FACTION_ARMORY',timestamp:o.timestamp||new Date().toISOString(),apiVerified:o.apiVerified===true,apiLogIds:o.apiLogIds||[],mvEachFrozen:price,preBalanceFaction:fBefore,preBalancePersonal:pBefore,allocations:[],claimIds:[],receiptBatchId:'',status:'ACTIVE',notes:''};const fr=consume(id,F,INV,fq,m.id),pr=consume(id,P,INV,pq,m.id);if(fr.unresolved||pr.unresolved)throw new Error('Could not allocate full deposit');m.allocations=fr.allocations.concat(pr.allocations);state.movements.push(m);m.allocations.forEach(a=>{const c=makeClaim(m,a,price);if(c)m.claimIds.push(c.id);});return m;}
function localMove(id,qty,from,to){id=String(id);qty=Math.max(1,Number(qty||1));const fa=balance(id,F,from),fq=Math.min(qty,fa),pq=qty-fq;if(pq>balance(id,P,from))throw new Error('Not enough tracked stock');const m={id:uid('MOV'),type:to===DISP?'DISPLAY_IN':'DISPLAY_OUT',itemId:id,itemName:itemName(id),qty,from,to,timestamp:new Date().toISOString(),apiVerified:false,apiLogIds:[],mvEachFrozen:mv(id),allocations:[],claimIds:[],receiptBatchId:'',status:'ACTIVE',notes:'Faction-owned stock allocated first.'},fr=consume(id,F,from,fq,m.id),pr=consume(id,P,from,pq,m.id);m.allocations=fr.allocations.concat(pr.allocations);state.movements.push(m);m.allocations.forEach(a=>addLot({itemId:id,itemName:m.itemName,owner:a.owner,location:to,qty:a.qty,sourceType:'LOCATION_TRANSFER',sourceRef:m.id,rootId:a.rootId,costBasisKnown:a.costBasisKnown,costEach:a.costEach,mvAtSource:a.mvAtSource}));return m;}

function factionPart(log){const d=log&&log.data&&typeof log.data==='object'?log.data:{},rows=Array.isArray(d.items)?d.items:(Array.isArray(d.item)?d.item:[]);if(!rows.length||d.faction==null)return null;const actor=String(state.settings.playerId||''),sender=d.sender==null?'':String(d.sender),receiver=d.receiver==null?'':String(d.receiver);if(!sender&&!receiver)return null;if(actor&&sender!==actor&&receiver!==actor)return null;return{logId:logId(log),timestamp:Number(log.timestamp||0),factionId:String(d.faction),sender,receiver,rows:rows.map(r=>({itemId:String(r.id||r.item_id||''),qty:Math.max(1,Number(r.qty||r.quantity||1))})).filter(r=>r.itemId)};}
function incomingParts(log){const d=log&&log.data&&typeof log.data==='object'?log.data:{};if(d.sender==null||d.receiver!=null||d.faction!=null)return[];if(d.cost_total!=null||d.cost_each!=null||d.seller!=null||d.buyer!=null)return[];const rows=Array.isArray(d.items)?d.items:(d.item&&typeof d.item==='object'?[d.item]:[]);return rows.map(r=>{const id=String(r.id||r.item_id||'');if(!id)return null;return{id:uid('TRN'),apiLogId:logId(log),timestamp:new Date(Number(log.timestamp||Math.floor(Date.now()/1000))*1000).toISOString(),senderId:String(d.sender),itemId:id,itemName:itemName(id),qty:Math.max(1,Number(r.qty||r.quantity||1)),status:'PENDING'};}).filter(Boolean);}

async function reconcilePurchases(logs){await ensureCatalog(false);let changed=false;for(const log of logs.slice().sort((a,b)=>Number(a.timestamp||0)-Number(b.timestamp||0))){const id=logId(log);if(!id||seen(id))continue;const d=log&&log.data&&typeof log.data==='object'?log.data:{};if(d.faction!=null)continue;const rows=Array.isArray(d.items)?d.items:[];if(!rows.length||(d.cost_total==null&&d.cost_each==null)||d.balance_before!=null||d.balance_after!=null)continue;const total=Math.max(0,Number(d.cost_total||0)),each=Math.max(0,Number(d.cost_each||0)),totalQty=rows.reduce((n,r)=>n+Math.max(1,Number(r&&(r.qty||r.quantity)||1)),0);let used=false;rows.forEach(r=>{const itemId=String(r&&(r.id||r.item_id)||''),qty=Math.max(1,Number(r&&(r.qty||r.quantity)||1)),it=itemById(itemId),name=it?it.name:'Item #'+itemId,w=whitelist(itemId,name);if(!itemId||!w)return;const logMs=Number(log.timestamp||0)*1000,addedMs=new Date(w.addedAt||0).getTime();if(addedMs&&logMs<addedMs)return;const costEach=each||(total&&totalQty?total/totalQty:0);addLot({itemId,itemName:name,owner:P,location:INV,qty,sourceType:'PURCHASE',sourceRef:id,costBasisKnown:costEach>0,costEach,mvAtSource:mv(itemId),createdAt:new Date(Number(log.timestamp||0)*1000).toISOString(),notes:'API-detected whitelisted purchase.'});used=changed=true;});if(used)remember(id);}return changed;}
async function reconcileIncoming(logs){await ensureCatalog(false);let changed=false;for(const log of logs){const id=logId(log);if(!id||seen(id))continue;if(!logAfterTrackingStart(log)){remember(id);continue;}const parts=incomingParts(log);if(!parts.length)continue;parts.forEach(p=>{if(!state.pendingTransfers.some(x=>x.apiLogId===p.apiLogId&&x.itemId===p.itemId&&x.status!=='VOID')){state.pendingTransfers.push(p);changed=true;}});remember(id);}return changed;}
async function reconcileArmory(logs){await ensureCatalog(false);let changed=false;const actor=String(state.settings.playerId||''),parts=logs.filter(logAfterTrackingStart).map(factionPart).filter(Boolean),groups=new Map();parts.forEach(p=>p.rows.forEach(r=>{const k=[p.timestamp,p.factionId,r.itemId,r.qty].join('|');if(!groups.has(k))groups.set(k,[]);groups.get(k).push({part:p,row:r});}));groups.forEach(entries=>{const s=entries.find(x=>actor&&x.part.sender===actor),r=entries.find(x=>actor&&x.part.receiver===actor);if(!s||!r)return;const ids=entries.map(x=>x.part.logId).filter(Boolean);if(ids.every(seen))return;const row=s.row,dup=state.movements.some(m=>m.type==='ARMORY_OUT'&&m.status!=='VOID'&&String(m.itemId)===row.itemId&&Number(m.qty)===row.qty&&m.apiLogIds&&m.apiLogIds.some(id=>ids.includes(id)));if(!dup){armoryOut({itemId:row.itemId,itemName:itemName(row.itemId),qty:row.qty,mvEach:mv(row.itemId),timestamp:new Date(s.part.timestamp*1000).toISOString(),apiVerified:true,apiLogIds:ids});changed=true;}ids.forEach(remember);});
 for(const log of logs.slice().sort((a,b)=>Number(a.timestamp||0)-Number(b.timestamp||0))){const id=logId(log);if(!id||seen(id))continue;if(!logAfterTrackingStart(log)){remember(id);continue;}const d=log&&log.data&&typeof log.data==='object'?log.data:{},rows=Array.isArray(d.items)?d.items:[];if(d.faction==null||!rows.length||d.sender!=null||d.receiver!=null||d.cost_total!=null||d.cost_each!=null||d.seller!=null)continue;let used=false;for(const row of rows){const itemId=String(row.id||row.item_id||''),qty=Math.max(1,Number(row.qty||row.quantity||1));if(!itemId)continue;if(state.movements.some(m=>m.type==='ARMORY_IN'&&m.status!=='VOID'&&Array.isArray(m.apiLogIds)&&m.apiLogIds.includes(id)&&String(m.itemId)===itemId))continue;const held=balance(itemId,F,INV),w=whitelist(itemId,itemName(itemId));if(!held&&!w){state.movements.push({id:uid('MOV'),type:'ARMORY_IN',itemId,itemName:itemName(itemId),qty,from:INV,to:'FACTION_ARMORY',timestamp:new Date(Number(log.timestamp||0)*1000).toISOString(),apiVerified:true,apiLogIds:[id],mvEachFrozen:mv(itemId),preBalanceFaction:0,preBalancePersonal:balance(itemId,P,INV),allocations:[],claimIds:[],receiptBatchId:'',status:'REVIEW',notes:'Non-whitelisted deposit with no tracked faction ownership. No reimbursement claim created.'});used=changed=true;continue;}try{armoryIn({itemId,itemName:itemName(itemId),qty,mvEach:mv(itemId),timestamp:new Date(Number(log.timestamp||0)*1000).toISOString(),apiVerified:true,apiLogIds:[id]});used=changed=true;}catch(e){console.warn('[FLIQ] deposit allocation review',e);}}if(used)remember(id);}return changed;}
async function poll(showToast=false){if(apiBusy)return;if(!apiKey()){state.diagnostics.apiStatus='API key required';if(showToast)toast('Add your Torn API key in Settings');render();return;}apiBusy=true;try{await ensureCatalog(false);const d=await apiFetch('user/log',{limit:'100'}),logs=logArray(d);state.diagnostics.lastLogCount=logs.length;await reconcilePurchases(logs);await reconcileArmory(logs);await reconcileIncoming(logs);state.diagnostics.apiStatus='Connected';state.diagnostics.lastApiError='';state.diagnostics.lastSyncAt=new Date().toISOString();save(false);render();if(showToast)toast('Ledger synced');}catch(e){state.diagnostics.apiStatus='Error';state.diagnostics.lastApiError=String(e&&e.message||e);save(false);render();if(showToast)toast('Sync failed: '+state.diagnostics.lastApiError);}finally{apiBusy=false;}}
function restartPolling(){if(apiTimer)clearInterval(apiTimer);apiTimer=null;if(!state.settings.apiPolling||!apiKey())return;const sec=Math.max(10,Number(state.settings.apiPollSeconds||15));apiTimer=setInterval(()=>poll(false),sec*1000);setTimeout(()=>poll(false),1200);}

function activeRaffle(){return state.raffles.find(r=>r.status==='OPEN')||null;}
function classifyRaffle(ids){const raf=activeRaffle();if(!raf)throw new Error('Start a raffle first');const set=new Set(ids||[]),rows=state.pendingTransfers.filter(t=>t.status==='PENDING'&&set.has(t.id));if(!rows.length)throw new Error('Select at least one transfer');rows.forEach(t=>{t.status='RAFFLE';t.raffleId=raf.id;t.classifiedAt=new Date().toISOString();addLot({itemId:t.itemId,itemName:t.itemName,owner:F,location:INV,qty:t.qty,sourceType:'RAFFLE',sourceRef:t.id,costBasisKnown:false,mvAtSource:mv(t.itemId),createdAt:t.timestamp,notes:'Raffle intake; faction-owned while held personally.'});});raf.transferIds=(raf.transferIds||[]).concat(rows.map(t=>t.id));save();toast(rows.length+' transfer(s) marked as raffle stock');}

function friendly(v){return({PERSONAL_INVENTORY:'Personal Inventory',DISPLAY_CASE:'Display Case',FACTION_ARMORY:'Faction Armory'}[v]||String(v||'').replaceAll('_',' '));}
function encodePayload(p){return btoa(unescape(encodeURIComponent(JSON.stringify(p)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/g,'');}
function decodePayload(code){let s=String(code||'').trim().replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return JSON.parse(decodeURIComponent(escape(atob(s))));}
function extractPayload(text){const m=String(text||'').match(/FLIQ-AUDIT:([A-Za-z0-9_-]+)/);if(!m)throw new Error('No FactionLedgerIQ audit code found');return decodePayload(m[1]);}
function movementPayload(moves){const batchId=uid('BATCH'),claims=[],rows=moves.map(m=>{const cs=(m.claimIds||[]).map(claimById).filter(Boolean);cs.forEach(c=>{if(c.status==='OPEN'){c.status='SUBMITTED';c.submittedAt=new Date().toISOString();}claims.push(c);});m.receiptBatchId=batchId;m.receiptGeneratedAt=new Date().toISOString();return{movementId:m.id,type:m.type,timestamp:m.timestamp,itemId:m.itemId,itemName:m.itemName,qty:m.qty,from:m.from,to:m.to,apiVerified:m.apiVerified===true,apiLogIds:m.apiLogIds||[],allocations:(m.allocations||[]).map(a=>({owner:a.owner,qty:a.qty,sourceType:a.sourceType})),claimIds:cs.map(c=>c.id)};});const p={kind:'MOVEMENT',version:VERSION,batchId,generatedAt:new Date().toISOString(),player:{name:state.settings.playerName||'',id:state.settings.playerId||''},factionName:state.settings.factionName||'',movements:rows,claims:claims.map(c=>({id:c.id,movementId:c.movementId,itemId:c.itemId,itemName:c.itemName,qty:c.qty,paidEach:c.paidEach,costBasisKnown:c.costBasisKnown,mvEachFrozen:c.mvEachFrozen,amount:c.amount,status:c.status}))};state.receiptBatches.push({id:batchId,kind:'MOVEMENT',generatedAt:p.generatedAt,movementIds:moves.map(m=>m.id),claimIds:claims.map(c=>c.id)});return p;}
function movementReceipt(p){const l=['**FACTION LEDGER IQ — ITEM MOVEMENT**','',`Player: ${p.player.name||'Unknown'}${p.player.id?' ['+p.player.id+']':''}`,p.factionName?'Faction: '+p.factionName:'',`Batch: \`${p.batchId}\``,''].filter(x=>x!==undefined);p.movements.forEach(m=>{const fq=(m.allocations||[]).filter(a=>a.owner===F).reduce((n,a)=>n+Number(a.qty||0),0),pq=(m.allocations||[]).filter(a=>a.owner===P).reduce((n,a)=>n+Number(a.qty||0),0),cs=p.claims.filter(c=>c.movementId===m.movementId),amt=cs.reduce((n,c)=>n+Number(c.amount||0),0);l.push(`**${m.itemName}**`,`Qty: ${Number(m.qty||0).toLocaleString()}`,`Movement: ${friendly(m.from)} → ${friendly(m.to)}`);if(fq)l.push('Faction-owned: '+fq.toLocaleString());if(pq)l.push('Personal: '+pq.toLocaleString());if(cs.length){l.push('Claim: **'+money(amt)+'**','Claim ID'+(cs.length>1?'s':'')+': '+cs.map(c=>'`'+c.id+'`').join(', '));}else l.push('Reimbursement: **$0**');l.push('API Verified: '+(m.apiVerified?'Yes':'No'),'');});l.push('**TOTAL CLAIMED:** '+money(p.claims.reduce((n,c)=>n+Number(c.amount||0),0)),'','FLIQ-AUDIT:'+encodePayload(p));return l.join('\n');}
function generateReceipt(){const moves=state.movements.filter(m=>m.status!=='VOID'&&!m.receiptBatchId&&['ARMORY_IN','ARMORY_OUT','DISPLAY_IN','DISPLAY_OUT'].includes(m.type));if(!moves.length){toast('No unreported movements');return;}const p=movementPayload(moves),text=movementReceipt(p);save(false);showReceipt('Discord Movement Receipt',text);render();}
function paymentReceipt(p){const l=['**FACTION LEDGER IQ — REIMBURSEMENT**','',`Paid To: ${p.member.name||'Unknown'}${p.member.id?' ['+p.member.id+']':''}`,`Recorded By: ${p.leadership.name||'Leadership'}${p.leadership.id?' ['+p.leadership.id+']':''}`,`Payment Batch: \`${p.batchId}\``,''];p.claims.forEach(c=>l.push(`**${c.itemName}**`,`Qty: ${Number(c.qty||0).toLocaleString()}`,'Paid: **'+money(c.amount)+'**',`Claim ID: \`${c.id}\``,' '));l.push('**TOTAL REIMBURSED:** '+money(p.total),'','FLIQ-AUDIT:'+encodePayload(p));return l.join('\n');}
async function verifyMovementPayload(p){const out={};p.movements.forEach(m=>out[m.movementId]=m.apiVerified?'MEMBER_VERIFIED':'UNVERIFIED');try{const d=await apiFetch('faction/news',{cat:'armoryDeposit,armoryAction',limit:'100'}),src=d&&(d.news||d),rows=Array.isArray(src)?src:(src&&typeof src==='object'?Object.keys(src).map(k=>src[k]).filter(Boolean):[]),flat=rows.map(r=>({ts:Number(r.timestamp||r.created_at||r.time||0),text:JSON.stringify(r).toLowerCase()}));p.movements.forEach(m=>{if(!['ARMORY_IN','ARMORY_OUT'].includes(m.type))return;const ts=Math.floor(new Date(m.timestamp).getTime()/1000),items=[String(m.itemName||'').toLowerCase(),String(m.itemId||'')].filter(Boolean),players=[String(p.player&&p.player.id||'').toLowerCase(),String(p.player&&p.player.name||'').toLowerCase()].filter(Boolean),hit=flat.some(r=>(!ts||!r.ts||Math.abs(r.ts-ts)<=900)&&items.some(n=>r.text.includes(n))&&players.some(n=>r.text.includes(n)));if(hit)out[m.movementId]='VERIFIED';});}catch(e){}return out;}
async function importReceipt(text){const p=extractPayload(text);if(p.kind==='PAYMENT'){let n=0;p.claims.forEach(x=>{const c=claimById(x.id);if(!c||c.status==='VOID')return;c.status='REIMBURSED';c.reimbursedAt=p.paidAt||p.generatedAt||new Date().toISOString();c.reimbursementBatchId=p.batchId;n++;});save();toast(n+' claim(s) marked reimbursed');return;}if(p.kind!=='MOVEMENT')throw new Error('Unsupported LedgerIQ receipt');const verification=await verifyMovementPayload(p),statuses=p.claims.map(c=>{const old=state.auditClaims.find(a=>a.claimId===c.id),m=p.movements.find(x=>x.movementId===c.movementId),v=m?verification[m.movementId]:'UNVERIFIED';let status='NEW';if(old&&old.status==='PAID')status='ALREADY_PAID';else if(old&&Number(old.amount||0)!==Number(c.amount||0))status='REVIEW';else if(v==='UNVERIFIED'||v==='MEMBER_VERIFIED')status='REVIEW';return{claim:c,existing:old,status,verification:v};});currentAudit={payload:p,verification,claimStatuses:statuses};activeTab='audit';render();}
function payAudit(){if(!currentAudit)return;const p=currentAudit.payload,payable=currentAudit.claimStatuses.filter(r=>r.status==='NEW');if(!payable.length){toast('No new verified claims to pay');return;}const paidAt=new Date().toISOString();payable.forEach(r=>{let a=state.auditClaims.find(x=>x.claimId===r.claim.id);if(!a){a={id:uid('AUD'),claimId:r.claim.id,sourceBatchId:p.batchId,playerName:p.player&&p.player.name||'',playerId:p.player&&p.player.id||'',itemId:r.claim.itemId,itemName:r.claim.itemName,qty:r.claim.qty,amount:r.claim.amount,status:'PAID',paidAt,importedAt:new Date().toISOString()};state.auditClaims.push(a);}else{a.status='PAID';a.paidAt=paidAt;}});const pay={kind:'PAYMENT',version:VERSION,batchId:uid('PAY'),generatedAt:new Date().toISOString(),paidAt,member:{name:p.player&&p.player.name||'',id:p.player&&p.player.id||''},leadership:{name:state.settings.playerName||'',id:state.settings.playerId||''},claims:payable.map(r=>({id:r.claim.id,itemId:r.claim.itemId,itemName:r.claim.itemName,qty:r.claim.qty,amount:r.claim.amount}))};pay.total=pay.claims.reduce((n,c)=>n+Number(c.amount||0),0);state.paymentBatches.push({id:pay.batchId,sourceBatchId:p.batchId,paidAt,claimIds:pay.claims.map(c=>c.id),total:pay.total});currentAudit=null;save(false);showReceipt('Discord Reimbursement Receipt',paymentReceipt(pay));render();}

function inventoryRows(){const map=new Map();activeLots().forEach(l=>{if(!state.settings.displayTracking&&l.location===DISP)return;const k=String(l.itemId);if(!map.has(k))map.set(k,{itemId:k,itemName:l.itemName||itemName(k),personal:0,faction:0,personalDisplay:0,factionDisplay:0,mv:mv(k)});const r=map.get(k);if(l.location===INV&&l.owner===P)r.personal+=Number(l.qtyRemaining||0);if(l.location===INV&&l.owner===F)r.faction+=Number(l.qtyRemaining||0);if(l.location===DISP&&l.owner===P)r.personalDisplay+=Number(l.qtyRemaining||0);if(l.location===DISP&&l.owner===F)r.factionDisplay+=Number(l.qtyRemaining||0);});return Array.from(map.values()).sort((a,b)=>a.itemName.localeCompare(b.itemName));}
function movementCard(m){const cs=(m.claimIds||[]).map(claimById).filter(Boolean),owed=cs.reduce((n,c)=>n+Number(c.amount||0),0),fq=(m.allocations||[]).filter(a=>a.owner===F).reduce((n,a)=>n+Number(a.qty||0),0),pq=(m.allocations||[]).filter(a=>a.owner===P).reduce((n,a)=>n+Number(a.qty||0),0);return `<div class="fliq-list-item"><div class="fliq-item-top"><div><div class="fliq-item-name">${esc(m.itemName)}</div><div class="fliq-muted">${esc(fmt(m.timestamp))}</div></div><span class="fliq-pill ${m.apiVerified?'green':'gold'}">${m.apiVerified?'API VERIFIED':'MANUAL'}</span></div><div>${Number(m.qty||0).toLocaleString()} · ${esc(friendly(m.from))} → ${esc(friendly(m.to))}</div><div class="fliq-muted">${fq?'Faction '+fq.toLocaleString()+' ':''}${pq?'Personal '+pq.toLocaleString():''}${owed?' · Owed '+money(owed):''}</div></div>`;}

function homeHtml(){const pending=state.pendingTransfers.filter(t=>t.status==='PENDING').length,unreported=state.movements.filter(m=>m.status!=='VOID'&&!m.receiptBatchId&&['ARMORY_IN','ARMORY_OUT','DISPLAY_IN','DISPLAY_OUT'].includes(m.type)).length,recent=state.movements.filter(m=>m.status!=='VOID').slice().sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp)).slice(0,6);return `<div class="fliq-grid"><div class="fliq-card"><h3>Personal Stock</h3><div class="fliq-big">${money(personalValue(P))}</div><div class="fliq-muted">Current MV</div></div><div class="fliq-card"><h3>Faction Held</h3><div class="fliq-big">${money(personalValue(F))}</div><div class="fliq-muted">Held by you</div></div><div class="fliq-card"><h3>Faction Owes You</h3><div class="fliq-big">${money(openClaimTotal())}</div><div class="fliq-muted">Open + submitted</div></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Sync</span><span class="${state.diagnostics.apiStatus==='Connected'?'fliq-good':'fliq-muted'}">${esc(state.diagnostics.apiStatus)}</span></div><div class="fliq-muted">${state.diagnostics.lastSyncAt?'Last sync: '+esc(fmt(state.diagnostics.lastSyncAt)):'No sync yet'}${state.diagnostics.lastApiError?'<br><span class="fliq-bad">'+esc(state.diagnostics.lastApiError)+'</span>':''}</div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="sync">Sync Now</button><button class="fliq-btn" data-fliq="refresh-mv">Refresh MV</button></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Needs Attention</span></div><div class="fliq-list"><div class="fliq-list-item"><b>${unreported}</b> movement${unreported===1?'':'s'} need a Discord receipt.${unreported?'<div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="generate-receipt">Generate Movement Receipt</button></div>':''}</div><div class="fliq-list-item"><b>${pending}</b> incoming transfer${pending===1?'':'s'} waiting for classification.${pending?'<div class="fliq-actions"><button class="fliq-btn" data-fliq="tab" data-tab="raffles">Open Raffles</button></div>':''}</div></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Recent Movement</span></div><div class="fliq-list">${recent.length?recent.map(movementCard).join(''):'<div class="fliq-muted">No movement recorded yet.</div>'}</div></div>`;}
function itemOptions(){return itemCatalog.slice(0,2500).map(i=>`<option value="${esc(i.name)} [${esc(i.id)}]"></option>`).join('');}
function inventoryHtml(){const rows=inventoryRows();return `<div class="fliq-section"><div class="fliq-section-title"><span>Add Current / Opening Stock</span><span class="fliq-muted">Optional</span></div><div class="fliq-muted">Add only the personal or faction-owned stock you want LedgerIQ to know about.</div><div class="fliq-row"><input id="fliq-open-item" class="fliq-input fliq-grow" list="fliq-items" placeholder="Item name or ID"><datalist id="fliq-items">${itemOptions()}</datalist><input id="fliq-open-qty" class="fliq-input" style="width:90px" type="number" min="1" placeholder="Qty"></div><div class="fliq-row"><select id="fliq-open-owner" class="fliq-select fliq-grow"><option value="PERSONAL">Personally Owned</option><option value="FACTION">Faction Owned</option></select>${state.settings.displayTracking?'<select id="fliq-open-location" class="fliq-select fliq-grow"><option value="PERSONAL_INVENTORY">Personal Inventory</option><option value="DISPLAY_CASE">Display Case</option></select>':'<input id="fliq-open-location" type="hidden" value="PERSONAL_INVENTORY">'}</div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="add-opening">Add Stock</button></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Tracked Inventory</span><span class="fliq-muted">${rows.length}</span></div>${rows.length?`<table class="fliq-table"><thead><tr><th>Item</th><th>Personal</th><th>Faction</th><th>Current MV</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.itemName)}</b>${state.settings.displayTracking?`<div class="fliq-muted">Display P ${r.personalDisplay.toLocaleString()} / F ${r.factionDisplay.toLocaleString()}</div>`:''}</td><td>${r.personal.toLocaleString()}</td><td>${r.faction.toLocaleString()}</td><td>${money(r.mv)}</td></tr>`).join('')}</tbody></table>`:'<div class="fliq-muted">No tracked inventory yet.</div>'}</div>${state.settings.displayTracking?`<div class="fliq-section"><div class="fliq-section-title"><span>Move To / From Display Case</span></div><div class="fliq-row"><input id="fliq-display-item" class="fliq-input fliq-grow" list="fliq-items" placeholder="Item"><input id="fliq-display-qty" class="fliq-input" style="width:90px" type="number" min="1" placeholder="Qty"></div><div class="fliq-actions"><button class="fliq-btn" data-fliq="display-in">To Display</button><button class="fliq-btn" data-fliq="display-out">To Personal</button></div></div>`:''}`;}
function rafflesHtml(){const raf=activeRaffle(),pending=state.pendingTransfers.filter(t=>t.status==='PENDING'),done=raf?state.pendingTransfers.filter(t=>t.raffleId===raf.id&&t.status==='RAFFLE'):[],total=done.reduce((n,t)=>n+mv(t.itemId)*Number(t.qty||0),0);return `<div class="fliq-section"><div class="fliq-section-title"><span>Raffle Intake</span>${raf?'<span class="fliq-pill green">ACTIVE</span>':'<span class="fliq-pill">NO ACTIVE RAFFLE</span>'}</div>${raf?`<div><b>${esc(raf.name)}</b>${raf.code?' · Code '+esc(raf.code):''}</div><div class="fliq-muted">${done.length} transfer${done.length===1?'':'s'} · ${money(total)} current MV</div><div class="fliq-actions"><button class="fliq-btn" data-fliq="close-raffle">Close Raffle</button></div>`:`<div class="fliq-row"><input id="fliq-raffle-name" class="fliq-input fliq-grow" placeholder="Raffle name"><input id="fliq-raffle-code" class="fliq-input" style="width:110px" placeholder="Code optional"></div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="start-raffle">Start Raffle</button></div>`}</div><div class="fliq-section"><div class="fliq-section-title"><span>Pending Incoming Transfers</span><span class="fliq-muted">${pending.length}</span></div>${pending.length?`<label class="fliq-row"><input id="fliq-raffle-all" type="checkbox" checked> Select all</label><div class="fliq-list">${pending.slice(0,150).map(t=>`<label class="fliq-list-item"><input class="fliq-raffle-check" type="checkbox" value="${esc(t.id)}" checked> <b>${esc(t.itemName)}</b> ×${Number(t.qty||0).toLocaleString()} <span class="fliq-muted">from ${esc(t.senderId)}</span></label>`).join('')}</div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="mark-raffle" ${raf?'':'disabled'}>Mark Selected as Raffle / Faction Owned</button></div>`:'<div class="fliq-muted">No incoming transfers waiting for classification.</div>'}</div><div class="fliq-section"><div class="fliq-muted">Raffle items remain physically in your Personal Inventory, but ownership is faction. Armory deposits consume faction-owned stock first and create $0 reimbursement for that quantity.</div></div>`;}
function claimsHtml(){const cs=state.claims.filter(c=>c.status!=='VOID').sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)),open=cs.filter(c=>c.status==='OPEN'||c.status==='SUBMITTED'),paid=cs.filter(c=>c.status==='REIMBURSED');return `<div class="fliq-section"><div class="fliq-section-title"><span>Awaiting Reimbursement</span><span class="fliq-big">${money(openClaimTotal())}</span></div><div class="fliq-list">${open.length?open.map(c=>`<div class="fliq-list-item"><div class="fliq-item-top"><div><div class="fliq-item-name">${esc(c.itemName)} ×${Number(c.qty||0).toLocaleString()}</div><div class="fliq-muted">${esc(c.id)}</div></div><span class="fliq-pill ${c.status==='SUBMITTED'?'gold':'red'}">${esc(c.status)}</span></div><div>MV frozen: ${money(c.mvEachFrozen)} ea${c.costBasisKnown?' · Paid '+money(c.paidEach)+' ea':' · Cost unknown'}</div><div><b>Owed: ${money(c.amount)}</b></div><div class="fliq-actions"><button class="fliq-btn fliq-btn-small" data-fliq="mark-reimbursed" data-id="${esc(c.id)}">Mark Reimbursed</button></div></div>`).join(''):'<div class="fliq-muted">Nothing is currently owed.</div>'}</div></div><div class="fliq-section"><div class="fliq-section-title"><span>Import Leadership Reimbursement Receipt</span></div><textarea id="fliq-payment-import" class="fliq-textarea" placeholder="Paste the leadership Discord reimbursement receipt"></textarea><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="import-payment">Import Receipt</button></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Reimbursement History</span><span class="fliq-muted">${paid.length}</span></div><div class="fliq-list">${paid.slice(0,30).map(c=>`<div class="fliq-list-item"><b>${esc(c.itemName)}</b> ×${Number(c.qty||0).toLocaleString()} · ${money(c.amount)}<div class="fliq-muted">${esc(fmt(c.reimbursedAt))} · ${esc(c.id)}</div></div>`).join('')||'<div class="fliq-muted">No reimbursements marked received yet.</div>'}</div></div>`;}
function auditHtml(){let result='';if(currentAudit){const p=currentAudit.payload,total=p.claims.reduce((n,c)=>n+Number(c.amount||0),0);result=`<div class="fliq-section"><div class="fliq-section-title"><span>Audit Result</span><span>${money(total)}</span></div><div><b>${esc(p.player&&p.player.name||'Unknown')}</b>${p.player&&p.player.id?' ['+esc(p.player.id)+']':''} · ${esc(p.batchId)}</div><div class="fliq-list" style="margin-top:8px">${currentAudit.claimStatuses.map(r=>`<div class="fliq-list-item"><div class="fliq-item-top"><div><b>${esc(r.claim.itemName)}</b> ×${Number(r.claim.qty||0).toLocaleString()} · ${money(r.claim.amount)}<div class="fliq-muted">${esc(r.claim.id)} · ${esc(r.verification)}</div></div><span class="fliq-pill ${r.status==='NEW'?'green':r.status==='ALREADY_PAID'?'red':'gold'}">${esc(r.status)}</span></div></div>`).join('')}</div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="audit-pay">Mark NEW Claims Paid + Create Receipt</button><button class="fliq-btn" data-fliq="audit-clear">Clear</button></div></div>`;}const paid=state.auditClaims.filter(a=>a.status==='PAID').slice().sort((a,b)=>new Date(b.paidAt)-new Date(a.paidAt)).slice(0,25);return `<div class="fliq-section"><div class="fliq-section-title"><span>Leadership Audit Import</span></div><div class="fliq-muted">Paste the member Discord movement receipt. Claim IDs are checked against paid history and Armory movement is checked against faction news when your key has access.</div><textarea id="fliq-audit-import" class="fliq-textarea" placeholder="Paste member movement receipt"></textarea><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="audit-import">Audit Receipt</button></div></div>${result}<div class="fliq-section"><div class="fliq-section-title"><span>Paid Claim History</span><span class="fliq-muted">${state.auditClaims.filter(a=>a.status==='PAID').length}</span></div><div class="fliq-list">${paid.map(a=>`<div class="fliq-list-item"><b>${esc(a.playerName||a.playerId)}</b> · ${esc(a.itemName)} ×${Number(a.qty||0).toLocaleString()} · ${money(a.amount)}<div class="fliq-muted">${esc(a.claimId)} · ${esc(fmt(a.paidAt))}</div></div>`).join('')||'<div class="fliq-muted">No leadership reimbursements recorded yet.</div>'}</div></div>`;}
function settingsHtml(){const wl=state.whitelist.slice().sort((a,b)=>a.itemName.localeCompare(b.itemName));return `<div class="fliq-section"><div class="fliq-section-title"><span>Profile</span></div><div class="fliq-row"><input id="fliq-set-name" class="fliq-input fliq-grow" value="${esc(state.settings.playerName)}" placeholder="Player name"><input id="fliq-set-id" class="fliq-input" style="width:120px" value="${esc(state.settings.playerId)}" placeholder="Player ID"></div><input id="fliq-set-faction" class="fliq-input" value="${esc(state.settings.factionName)}" placeholder="Faction name"></div><div class="fliq-section"><div class="fliq-section-title"><span>Torn API</span></div><input id="fliq-set-api" class="fliq-input" type="password" value="${esc(state.settings.apiKey)}" placeholder="Torn API key"><div class="fliq-row"><label><input id="fliq-set-poll" type="checkbox" ${state.settings.apiPolling?'checked':''}> Auto sync</label><input id="fliq-set-seconds" class="fliq-input" style="width:80px" type="number" min="10" value="${esc(state.settings.apiPollSeconds)}"><span class="fliq-muted">seconds</span></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Inventory Options</span></div><label class="fliq-row"><input id="fliq-set-display" type="checkbox" ${state.settings.displayTracking?'checked':''}> Track Display Case inventory</label><label class="fliq-row"><input id="fliq-set-show-faction" type="checkbox" ${state.settings.showAllFactionItems?'checked':''}> Show all faction-owned items</label></div><div class="fliq-section"><div class="fliq-section-title"><span>Whitelist</span><span class="fliq-muted">${wl.length}</span></div><div class="fliq-muted">Whitelist controls automatic personal purchase tracking. All faction Armory withdrawals are tracked even if not whitelisted.</div><div class="fliq-row"><input id="fliq-whitelist-item" class="fliq-input fliq-grow" list="fliq-items-settings" placeholder="Item name or ID"><datalist id="fliq-items-settings">${itemOptions()}</datalist><button class="fliq-btn" data-fliq="add-whitelist">Add</button></div><div class="fliq-list">${wl.map(w=>`<div class="fliq-list-item"><div class="fliq-item-top"><div><b>${esc(w.itemName)}</b><div class="fliq-muted">ID ${esc(w.itemId)} · MV ${money(mv(w.itemId))}</div></div><button class="fliq-btn fliq-btn-small" data-fliq="remove-whitelist" data-id="${esc(w.itemId)}">Remove</button></div></div>`).join('')||'<div class="fliq-muted">No whitelisted items yet.</div>'}</div></div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="save-settings">Save Settings</button><button class="fliq-btn" data-fliq="load-items">Load / Refresh Items</button></div>`;}

function installStyles(){if(document.getElementById(STYLE_ID))return;const s=document.createElement('style');s.id=STYLE_ID;s.textContent=`#${PANEL_ID}{position:fixed;z-index:999999;right:8px;top:52px;width:min(480px,calc(100vw - 16px));max-height:calc(100vh - 64px);overflow:hidden;border:1px solid rgba(120,120,120,.35);border-radius:10px;background:#f3f3f3;color:#222;box-shadow:0 14px 40px rgba(0,0,0,.35);font:13px/1.35 Arial,sans-serif}#${PANEL_ID}.hidden{display:none}#${PANEL_ID} *{box-sizing:border-box}.fliq-head{display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:#242424;color:#fff;border-bottom:3px solid #d34b4b}.fliq-brand{font-weight:700;font-size:15px}.fliq-version{font-size:10px;color:#bbb;margin-left:6px}.fliq-close{border:0;background:transparent;color:#ddd;font-size:20px;cursor:pointer}.fliq-tabs{display:flex;gap:2px;padding:6px;background:#ddd;overflow-x:auto}.fliq-tab{border:0;border-radius:6px;padding:7px 9px;background:#eee;color:#333;font-weight:700;white-space:nowrap}.fliq-tab.active{background:#d34b4b;color:#fff}.fliq-body{padding:10px;overflow:auto;max-height:calc(100vh - 142px)}.fliq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.fliq-card,.fliq-section{background:#fff;border:1px solid #d3d3d3;border-radius:8px;padding:9px}.fliq-section{margin-top:9px}.fliq-card h3{font-size:11px;text-transform:uppercase;color:#777;margin:0 0 4px}.fliq-big{font-size:18px;font-weight:800}.fliq-section-title{display:flex;justify-content:space-between;align-items:center;font-weight:800;margin-bottom:8px}.fliq-muted{color:#777;font-size:11px}.fliq-good{color:#2e7d32}.fliq-bad{color:#b3261e}.fliq-row{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin:6px 0}.fliq-grow{flex:1 1 140px}.fliq-input,.fliq-select,.fliq-textarea{width:100%;border:1px solid #bdbdbd;border-radius:6px;background:#fff;color:#222;padding:8px;font:inherit}.fliq-textarea{min-height:120px;resize:vertical}.fliq-btn{border:1px solid #aaa;border-radius:6px;background:#eee;color:#222;padding:7px 10px;font-weight:700;cursor:pointer}.fliq-btn-primary{background:#d34b4b;color:#fff;border-color:#b63b3b}.fliq-btn-small{padding:4px 7px;font-size:11px}.fliq-list{display:flex;flex-direction:column;gap:6px}.fliq-list-item{border:1px solid #ddd;border-radius:7px;padding:8px;background:#fafafa}.fliq-item-top{display:flex;justify-content:space-between;gap:8px;align-items:flex-start}.fliq-item-name{font-weight:800}.fliq-pill{display:inline-block;border-radius:999px;padding:2px 7px;font-size:10px;font-weight:800;background:#e5e5e5}.fliq-pill.red{background:#f5d5d5;color:#8e2222}.fliq-pill.green{background:#d9efdc;color:#286a30}.fliq-pill.gold{background:#f3e6c7;color:#7b5b15}.fliq-table{width:100%;border-collapse:collapse}.fliq-table th,.fliq-table td{padding:6px 4px;border-bottom:1px solid #e4e4e4;text-align:left;vertical-align:top}.fliq-table th{font-size:10px;color:#777;text-transform:uppercase}.fliq-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}#fliq-v1-toast{position:fixed;z-index:1000002;left:50%;bottom:24px;transform:translateX(-50%) translateY(20px);opacity:0;background:#242424;color:#fff;border-radius:8px;padding:9px 13px;transition:.18s;pointer-events:none;max-width:90vw}#fliq-v1-toast.show{opacity:1;transform:translateX(-50%) translateY(0)}#fliq-v1-modal{position:fixed;z-index:1000001;inset:0;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;padding:12px}#fliq-v1-modal .box{width:min(620px,100%);max-height:90vh;overflow:auto;border-radius:10px;background:#f4f4f4;color:#222;padding:12px;box-shadow:0 16px 50px rgba(0,0,0,.45)}@media(prefers-color-scheme:dark){#${PANEL_ID}{background:#202020;color:#eee;border-color:#444}.fliq-tabs{background:#181818}.fliq-tab{background:#333;color:#ddd}.fliq-card,.fliq-section{background:#292929;border-color:#444}.fliq-list-item{background:#242424;border-color:#444}.fliq-input,.fliq-select,.fliq-textarea{background:#1c1c1c;color:#eee;border-color:#555}.fliq-btn{background:#3a3a3a;color:#eee;border-color:#555}.fliq-table th,.fliq-table td{border-color:#444}.fliq-muted{color:#aaa}#fliq-v1-modal .box{background:#242424;color:#eee}}`;document.head.appendChild(s);}
function findDockAnchor(){return document.getElementById('notes_panel_button')||document.getElementById('people_panel_button');}
function ensureDock(){if(document.getElementById(DOCK_ID))return;const a=findDockAnchor();if(!a||!a.parentNode)return;const b=document.createElement('button');b.id=DOCK_ID;b.type='button';b.className=a.className;b.textContent='L';b.title='FactionLedgerIQ v'+VERSION;b.setAttribute('aria-label','Open FactionLedgerIQ');const box=a.getBoundingClientRect();if(box.width>=18&&box.width<=64)b.style.width=Math.round(box.width)+'px';if(box.height>=18&&box.height<=64)b.style.height=Math.round(box.height)+'px';b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();togglePanel();});a.parentNode.appendChild(b);}
function startDockObserver(){if(dockObserver)return;dockObserver=new MutationObserver(()=>{if(dockQueued)return;dockQueued=true;requestAnimationFrame(()=>{dockQueued=false;ensureDock();});});dockObserver.observe(document.body||document.documentElement,{childList:true,subtree:true});}
function ensurePanel(){installStyles();let p=document.getElementById(PANEL_ID);if(p)return p;p=document.createElement('div');p.id=PANEL_ID;p.className='hidden';document.body.appendChild(p);return p;}
function togglePanel(){const p=ensurePanel();p.classList.toggle('hidden');if(!p.classList.contains('hidden'))render();}
function render(){const p=ensurePanel(),hidden=p.classList.contains('hidden'),tabs=[['home','Home'],['inventory','Inventory'],['raffles','Raffles'],['claims','Claims'],['audit','Audit'],['settings','Settings']],body=activeTab==='inventory'?inventoryHtml():activeTab==='raffles'?rafflesHtml():activeTab==='claims'?claimsHtml():activeTab==='audit'?auditHtml():activeTab==='settings'?settingsHtml():homeHtml();p.innerHTML=`<div class="fliq-head"><div class="fliq-brand">FactionLedgerIQ <span class="fliq-version">v${esc(VERSION)}</span></div><button class="fliq-close" data-fliq="close">×</button></div><div class="fliq-tabs">${tabs.map(t=>`<button class="fliq-tab ${activeTab===t[0]?'active':''}" data-fliq="tab" data-tab="${t[0]}">${t[1]}</button>`).join('')}</div><div class="fliq-body">${body}</div>`;if(hidden)p.classList.add('hidden');}
function showReceipt(title,text){document.getElementById('fliq-v1-modal')?.remove();const m=document.createElement('div');m.id='fliq-v1-modal';m.innerHTML=`<div class="box"><div class="fliq-section-title"><span>${esc(title)}</span><button class="fliq-close" data-modal-close>×</button></div><textarea id="fliq-v1-receipt" class="fliq-textarea" style="min-height:360px">${esc(text)}</textarea><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-modal-copy>Copy Receipt</button><button class="fliq-btn" data-modal-close>Close</button></div></div>`;document.body.appendChild(m);m.addEventListener('click',async e=>{if(e.target.matches('[data-modal-close]')){m.remove();return;}if(e.target.matches('[data-modal-copy]')){const ta=m.querySelector('#fliq-v1-receipt');try{await navigator.clipboard.writeText(ta.value);}catch(err){ta.focus();ta.select();document.execCommand('copy');}toast('Receipt copied');}});}

async function action(t){const a=t.dataset.fliq;if(!a)return;if(a==='close'){ensurePanel().classList.add('hidden');return;}if(a==='tab'){activeTab=t.dataset.tab||'home';render();return;}if(a==='sync'){t.disabled=true;await poll(true);return;}if(a==='refresh-mv'||a==='load-items'){try{await ensureCatalog(true);save();toast('Market values refreshed');}catch(e){toast('Refresh failed: '+String(e&&e.message||e));}return;}if(a==='generate-receipt'){generateReceipt();return;}if(a==='save-settings'){state.settings.playerName=String(document.getElementById('fliq-set-name').value||'').trim();state.settings.playerId=String(document.getElementById('fliq-set-id').value||'').trim();state.settings.factionName=String(document.getElementById('fliq-set-faction').value||'').trim();state.settings.apiKey=String(document.getElementById('fliq-set-api').value||'').trim();state.settings.apiPolling=!!document.getElementById('fliq-set-poll').checked;state.settings.apiPollSeconds=Math.max(10,Number(document.getElementById('fliq-set-seconds').value||15));state.settings.displayTracking=!!document.getElementById('fliq-set-display').checked;state.settings.showAllFactionItems=!!document.getElementById('fliq-set-show-faction').checked;save();restartPolling();toast('Settings saved');return;}if(a==='add-whitelist'){const i=parseItem(document.getElementById('fliq-whitelist-item').value);if(!i||!i.id){toast('Load items and choose an item');return;}if(!state.whitelist.some(w=>String(w.itemId)===String(i.id)))state.whitelist.push({itemId:String(i.id),itemName:i.name,addedAt:new Date().toISOString()});save();return;}if(a==='remove-whitelist'){state.whitelist=state.whitelist.filter(w=>String(w.itemId)!==String(t.dataset.id));save();return;}if(a==='add-opening'){const i=parseItem(document.getElementById('fliq-open-item').value),q=Number(document.getElementById('fliq-open-qty').value||0),owner=document.getElementById('fliq-open-owner').value,loc=document.getElementById('fliq-open-location').value;if(!i||!Number.isInteger(q)||q<=0){toast('Choose an item and whole quantity');return;}addLot({itemId:i.id,itemName:i.name,owner,location:loc,qty:q,sourceType:'OPENING',costBasisKnown:false,mvAtSource:mv(i.id),notes:'Opening stock entered manually.'});save();toast('Stock added');return;}if(a==='display-in'||a==='display-out'){const i=parseItem(document.getElementById('fliq-display-item').value),q=Number(document.getElementById('fliq-display-qty').value||0);if(!i||!Number.isInteger(q)||q<=0){toast('Choose an item and quantity');return;}try{localMove(i.id,q,a==='display-in'?INV:DISP,a==='display-in'?DISP:INV);save();}catch(e){toast(String(e&&e.message||e));}return;}if(a==='start-raffle'){if(activeRaffle()){toast('Close current raffle first');return;}const name=String(document.getElementById('fliq-raffle-name').value||'').trim(),code=String(document.getElementById('fliq-raffle-code').value||'').trim();if(!name){toast('Enter a raffle name');return;}state.raffles.push({id:uid('RAF'),name,code,status:'OPEN',startedAt:new Date().toISOString(),closedAt:'',transferIds:[]});save();return;}if(a==='close-raffle'){const r=activeRaffle();if(r){r.status='CLOSED';r.closedAt=new Date().toISOString();save();}return;}if(a==='mark-raffle'){try{classifyRaffle(Array.from(document.querySelectorAll('.fliq-raffle-check:checked')).map(x=>x.value));}catch(e){toast(String(e&&e.message||e));}return;}if(a==='mark-reimbursed'){const c=claimById(t.dataset.id);if(c&&c.status!=='VOID'){c.status='REIMBURSED';c.reimbursedAt=new Date().toISOString();save();toast('Claim marked reimbursed');}return;}if(a==='import-payment'){try{await importReceipt(String(document.getElementById('fliq-payment-import').value||''));}catch(e){toast('Import failed: '+String(e&&e.message||e));}return;}if(a==='audit-import'){try{t.disabled=true;t.textContent='Checking…';await importReceipt(String(document.getElementById('fliq-audit-import').value||''));}catch(e){toast('Audit failed: '+String(e&&e.message||e));t.disabled=false;t.textContent='Audit Receipt';}return;}if(a==='audit-pay'){payAudit();return;}if(a==='audit-clear'){currentAudit=null;render();return;}}
function installEvents(){document.addEventListener('click',e=>{const t=e.target.closest('[data-fliq]');if(t)action(t);});document.addEventListener('change',e=>{if(e.target&&e.target.id==='fliq-raffle-all')document.querySelectorAll('.fliq-raffle-check').forEach(x=>x.checked=e.target.checked);});}
function boot(){const cleanedPurchases=purgePreWhitelistPurchases(),cleanedHistory=purgePreTrackingEvents();if(cleanedPurchases||cleanedHistory)save(false);installStyles();ensurePanel();ensureDock();startDockObserver();installEvents();restartPolling();if(apiKey())ensureCatalog(false).then(()=>{save(false);render();}).catch(()=>{});render();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
